begin;

-- program-deadline-alert: HTML shell matches career-readiness-program-launch (00130) / project-completion-nudge (00132); body + text match supplied copy.
update public.email_templates
set
  html_template = $pda140_html$<!DOCTYPE html><html><head><meta charset="utf-8"/><meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Complete your remaining steps before {{deadline_date}}</title></head><body style="margin:0;padding:0;background-color:#F8FAFC;font-family:Arial,Helvetica,sans-serif;color:#111827;-webkit-text-size-adjust:100%;"><div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:transparent;opacity:0;">{{email_preheader_text}}</div><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#F8FAFC" style="background-color:#F8FAFC;mso-table-lspace:0;mso-table-rspace:0;"><tr><td align="center" style="padding:24px 12px;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#ffffff" style="max-width:680px;background-color:#ffffff;border:1px solid #E5E7EB;border-radius:10px;mso-table-lspace:0;mso-table-rspace:0;"><tr><td bgcolor="#FFFFFF" style="background-color:#FFFFFF;border-bottom:2px solid #F59E0B;padding:22px 24px;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#FFFFFF" style="background-color:#FFFFFF;width:100%;mso-table-lspace:0;mso-table-rspace:0;"><tr><td width="52" valign="middle" bgcolor="#FFFFFF" style="background-color:#FFFFFF;padding:0 12px 0 0;vertical-align:middle;"><img src="{{email_logo_url}}" width="48" height="48" alt="NextGen CTO Logo" style="width:48px;height:auto;display:block;border:0;border-radius:8px;outline:none;text-decoration:none;"/></td><td valign="middle" bgcolor="#FFFFFF" style="background-color:#FFFFFF;color:#1E3A8A;font-size:18px;font-weight:800;line-height:1.25;padding:0;vertical-align:middle;">{{email_header_display}}</td></tr></table></td></tr><tr><td bgcolor="#ffffff" style="background-color:#FFFFFF;padding:20px 22px 24px 22px;"><p style="margin:0 0 8px 0;font-size:12px;font-weight:700;color:#F59E0B;text-transform:uppercase;letter-spacing:0.08em;">Deadline Alert</p><h1 style="margin:0 0 10px 0;font-size:26px;line-height:1.25;color:#0F172A;font-weight:800;">Complete your remaining steps before {{deadline_date}}</h1><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="margin:0 0 18px 0;"><tr><td height="2" bgcolor="#F59E0B" style="background-color:#F59E0B;font-size:0;line-height:0;">&nbsp;</td></tr></table><p style="margin:0 0 14px 0;font-size:15px;line-height:1.7;color:#334155;">Hi <strong>{{first_name}}</strong>,</p><table role="presentation" cellspacing="0" cellpadding="0" border="0" style="margin:0 0 22px 0;"><tr><td align="left"><a href="{{cta_url}}" style="display:inline-block;background:linear-gradient(135deg,#e58c33 0%,#d97a1f 100%);color:#FFFFFF;text-decoration:none;font-family:Arial,Helvetica,sans-serif;font-size:16px;font-weight:700;padding:14px 22px;border-radius:50px;box-shadow:0 6px 20px rgba(229,140,51,0.35);letter-spacing:0.5px;">{{cta_label}}</a></td></tr></table><p style="margin:0 0 12px 0;font-size:15px;line-height:1.7;color:#334155;">A quick reminder &mdash; the deadline to complete your remaining steps in {{program_name}} is {{deadline_date}}.</p><p style="margin:0 0 12px 0;font-size:15px;line-height:1.7;color:#334155;">This is not to create pressure.</p><p style="margin:0 0 12px 0;font-size:15px;line-height:1.7;color:#334155;">It is to make sure you do not miss progress because of a few pending tasks.</p><p style="margin:0 0 8px 0;font-size:15px;line-height:1.7;color:#334155;">Sometimes students complete most of the journey but delay small things like:</p><ul style="margin:0 0 18px 0;padding-left:18px;"><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Project submission</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Profile updates</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Resume, GitHub, or LinkedIn work</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Readiness activities</li><li style="margin:0 0 0px 0;font-size:14px;line-height:1.6;color:#334155;">Final checklist items</li></ul><p style="margin:0 0 16px 0;font-size:15px;line-height:1.7;color:#334155;">These small pending steps can affect your completion status later.</p><p style="margin:0 0 8px 0;font-size:15px;line-height:1.7;color:#334155;">So take a few minutes today and check what is still left.</p><p style="margin:0 0 8px 0;font-size:15px;font-weight:700;color:#0F172A;">Your next step is simple:</p><ul style="margin:0 0 18px 0;padding-left:18px;"><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Open your dashboard.</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Review the pending items.</li><li style="margin:0 0 0px 0;font-size:14px;line-height:1.6;color:#334155;">Complete whatever is still marked incomplete.</li></ul><p style="margin:0 0 6px 0;font-size:15px;font-weight:700;color:#0F172A;">If you are stuck, do not wait till the last day.</p><p style="margin:0 0 8px 0;font-size:15px;line-height:1.7;color:#334155;">Use the support channel here: <a href="{{support_url}}" style="color:#F4A854;text-decoration:none;font-weight:600;">{{support_url}}</a></p><p style="margin:0 0 8px 0;font-size:15px;font-weight:700;color:#0F172A;">You can also open your dashboard here:</p><p style="margin:0 0 8px 0;font-size:15px;line-height:1.7;color:#334155;"><a href="{{dashboard_url}}" style="color:#2563EB;text-decoration:underline;">{{dashboard_url}}</a></p><p style="margin:0 0 12px 0;font-size:14px;line-height:1.6;color:#64748B;">You are receiving this email because you are a subscriber of NextGen CTO.</p><p style="margin:0;font-size:14px;line-height:1.6;color:#64748B;">Unsubscribe or manage preferences:<br/><a href="{{unsubscribe_url}}" style="color:#64748B;text-decoration:underline;">{{unsubscribe_url}}</a></p></td></tr><tr><td align="center" bgcolor="#ffffff" style="text-align:center;margin-top:50px;font-size:0.9em;color:#777;padding:25px 20px;background:#ffffff;background-color:#ffffff;"><table role="presentation" cellspacing="0" cellpadding="0" border="0" align="center" style="margin:0 auto;"><tr><td valign="middle" style="padding-right:10px;"><a href="{{email_website_url}}" target="_blank" rel="noopener noreferrer" style="text-decoration:none;"><img src="{{email_logo_url}}" alt="NextGen CTO" width="56" style="display:block;border:0;outline:none;text-decoration:none;height:auto;"/></a></td><td valign="middle" style="font-family:Arial,Helvetica,sans-serif;font-size:18px;font-weight:700;line-height:1.2;color:#1E335C;">NextGen CTO</td></tr></table><div style="margin:auto;text-align:center;"><p style="color:#172B4D;font-size:14px;font-weight:600;">Follow us on</p><table role="presentation" cellspacing="0" cellpadding="0" border="0" align="center" style="margin:0 auto;"><tr><td style="padding:0 6px;"><a href="https://www.instagram.com/code.with.ctobhaiya?igsh=MTgyM3ZyY2V6enJheQ==" style="cursor:pointer;text-decoration:none;"><img src="https://algozenith.s3.ap-south-1.amazonaws.com/content/07-06-24/8059_a58afaf2-29b8-4761-9c0e-6d9fc6ae6f4a.png" style="width:40px;height:40px;" alt="Instagram"/></a></td><td style="padding:0 6px;"><a href="https://www.linkedin.com/in/anuj-kumar-a-k-a-cto-bhaiya-on-youtube-9a188968/" style="cursor:pointer;text-decoration:none;"><img src="https://algozenith.s3.ap-south-1.amazonaws.com/content/07-06-24/8059_44a6715c-441d-43f8-b5ee-bad637d717d3.png" style="width:40px;height:40px;" alt="LinkedIn"/></a></td><td style="padding:0 6px;"><a href="https://www.youtube.com/@CodingwithCTOBhaiya" style="cursor:pointer;text-decoration:none;"><img src="https://algozenith.s3.ap-south-1.amazonaws.com/content/07-06-24/8059_11a31c49-ba39-442b-81ac-b0816e2a71a1.png" style="width:40px;height:40px;" alt="YouTube"/></a></td></tr></table></div><div style="flex-grow:1;height:1px;background-color:black;margin-top:2rem;"></div><p style="font-weight:300;margin:0;padding:0;text-align:center;font-size:15px;">If you are no longer interested, click <a href="{{unsubscribe_url}}">here</a> to unsubscribe.</p><p style="font-weight:300;margin-top:6px;text-align:center;font-size:15px;">&copy; Copyright 2025. NextGen CTO Pvt Ltd. All Rights Reserved.</p></td></tr></table></td></tr></table></body></html>$pda140_html$,
  text_template = $pda140_txt$Complete your remaining steps before {{deadline_date}}

Hi {{first_name}},

A quick reminder — the deadline to complete your remaining steps in {{program_name}} is {{deadline_date}}.

This is not to create pressure.

It is to make sure you do not miss progress because of a few pending tasks.

Sometimes students complete most of the journey but delay small things like:

Project submission
Profile updates
Resume, GitHub, or LinkedIn work
Readiness activities
Final checklist items

These small pending steps can affect your completion status later.

So take a few minutes today and check what is still left.

Your next step is simple:

Open your dashboard.
Review the pending items.
Complete whatever is still marked incomplete.

{{cta_label}}: {{cta_url}}

If you are stuck, do not wait till the last day.

Use the support channel here: {{support_url}}

You can also open your dashboard here:

{{dashboard_url}}

You are receiving this email because you are a subscriber of NextGen CTO.

Unsubscribe or manage preferences:
{{unsubscribe_url}}$pda140_txt$,
  variables = '[{"key":"email_logo_url","label":"Brand logo URL","required":false,"sample":"https://www.nextgen-cto.in/assets/logo-hd.png","inputType":"url","source":"system","helpText":"Public HTTPS URL from EMAIL_BRAND_LOGO_URL or NEXT_PUBLIC_EMAIL_BRAND_LOGO_URL."},{"key":"first_name","label":"Recipient first name","required":false,"sample":"Anuj","inputType":"text","source":"recipient"},{"key":"college_name","label":"College name","required":false,"sample":"MAIT","inputType":"text","source":"recipient"},{"key":"program_name","label":"Program name","required":true,"sample":"NextGen CTO Career Readiness Program","inputType":"text","source":"campaign"},{"key":"deadline_date","label":"Deadline date","required":true,"sample":"30 May 2025","inputType":"date","source":"campaign"},{"key":"cta_url","label":"CTA URL","required":true,"placeholder":"https://...","inputType":"url","source":"campaign"},{"key":"cta_label","label":"CTA button text","required":true,"sample":"View checklist","inputType":"text","source":"campaign"},{"key":"dashboard_url","label":"Dashboard URL","required":false,"placeholder":"https://...","inputType":"url","source":"system"},{"key":"support_url","label":"Support URL","required":true,"placeholder":"https://...","inputType":"url","source":"campaign"},{"key":"unsubscribe_url","label":"Unsubscribe URL","required":false,"inputType":"url","source":"system","helpText":"System-generated on send. Preview-only in Email Center."}]'::jsonb,
  updated_at = now()
where slug = 'program-deadline-alert';

commit;
